INSERT INTO "public"."papers" ("id", "title", "abstract", "authors", "venue_id", "status", "pdf_url", "code_url", "created_at", "abstract_embedding") VALUES
	('04ed520e-d994-485e-90ee-fdf2c61245d6', 'Learning from Label Proportions by Learning with Label Noise', 'Learning from label proportions (LLP) is a weakly supervised classification problem where data points are grouped into bags, and the label proportions within each bag are observed instead of the instance-level labels. The task is to learn a classifier to predict the labels of future individual instances. Prior work on LLP for multi-class data has yet to develop a theoretically grounded algorithm. In this work, we propose an approach to LLP based on a reduction to learning with label noise, using the forward correction (FC) loss of \textcite{Patrini2017MakingDN}. We establish an excess risk bound and generalization error analysis for our approach, while also extending the theory of the FC loss which may be of independent interest. Our approach demonstrates improved empirical performance in deep learning scenarios across multiple datasets and architectures, compared to the leading methods.', '{"Zhang, Jianxin","Wang, Yutong","Scott, Clay"}', '95cb81ae-75ab-4437-9cf3-b1477cd0cd71', 'submitted', 'https://proceedings.neurips.cc/paper_files/paper/2022/file/ac56fb3fab015124b541f6299016a21c-Paper-Conference.pdf', NULL, '2025-02-13 18:19:46.080281+00', '[0.020987794,-0.05055431,-0.010559706,-0.045689236,0.008994447,0.061856408,0.028089888,0.027307631,0.04089409,-0.014338818,0.02546592,-0.043591205,0.029844169,0.062537916,0.01505995,-0.013956478,0.021894151,0.06002339,-0.06352327,-0.045397818,0.0047843796,-0.038203735,0.010391957,-0.017426942,0.0108677065,0.03998945,-0.018499708,-0.096220076,-0.0598462,-0.268502,0.038041793,-0.041521206,0.064989716,-0.02340454,0.024646364,-0.02756534,-0.03874513,0.016516145,-0.024443429,0.059136707,0.020068923,0.029619409,-0.035554644,-0.078761905,-0.028965952,0.00399898,-0.02135874,-0.05101779,-0.0015068055,-0.019044809,0.045271326,-0.05600524,-0.014713939,0.06481052,0.0014277202,0.05134099,0.065282546,0.039065048,0.055778287,0.06210778